<?php
if(!defined('ABSPATH'))exit;
class Terttus_Header_Widget extends \Elementor\Widget_Base{
public function get_name(){return'terttus_header';}public function get_title(){return'Terttus Shop Header';}public function get_icon(){return'eicon-site-logo';}public function get_categories(){return['terttus-widgets'];}
protected function register_controls(){$this->start_controls_section('c',['label'=>'Header']);$this->add_control('logo',['label'=>'Logo','type'=>\Elementor\Controls_Manager::MEDIA]);$this->add_control('shipping',['label'=>'Toptekst','type'=>\Elementor\Controls_Manager::TEXT,'default'=>'🚚 Fri fragt ved køb over 499 kr. · Levering 1–3 hverdage']);$this->add_control('search_placeholder',['label'=>'Søgetekst','type'=>\Elementor\Controls_Manager::TEXT,'default'=>'Søg efter produkter...']);$this->end_controls_section();}
protected function render(){$s=$this->get_settings_for_display();$cart=class_exists('WooCommerce')?wc_get_cart_url():'#';?><header class="tt-head terttus-widget"><div class="tt-top"><?php echo esc_html($s['shipping']);?></div><div class="terttus-container"><div class="tt-main"><a href="<?php echo esc_url(home_url('/'));?>" class="tt-logo"><?php if(!empty($s['logo']['url'])):?><img src="<?php echo esc_url($s['logo']['url']);?>" alt="<?php echo esc_attr(get_bloginfo('name'));?>"><?php else: ?><strong>Terttus<span>.dk</span></strong><?php endif; ?></a><form role="search" method="get" action="<?php echo esc_url(home_url('/'));?>"><input name="s" type="search" placeholder="<?php echo esc_attr($s['search_placeholder']);?>"><input type="hidden" name="post_type" value="product"><button aria-label="Søg">Søg</button></form><a class="tt-cart" href="<?php echo esc_url($cart);?>"><span>🛒</span> Kurv<?php if(class_exists('WooCommerce')&&WC()->cart):?><b><?php echo(int)WC()->cart->get_cart_contents_count();?></b><?php endif; ?></a></div><nav class="tt-nav"><?php wp_nav_menu(['theme_location'=>'primary','container'=>false,'fallback_cb'=>false]);?></nav></div></header><style>.tt-head{background:#fff;color:var(--tt-navy);box-shadow:0 1px 0 rgba(16,33,45,.07)}.tt-top{text-align:center;background:var(--tt-navy);color:#fff;padding:9px 15px;font-size:14px}.tt-main{display:grid;grid-template-columns:160px 1fr auto;gap:24px;align-items:center;padding:18px 0}.tt-logo{text-decoration:none;font-size:28px;color:var(--tt-teal)}.tt-logo span{color:var(--tt-orange)}.tt-logo img{max-height:50px;max-width:155px}.tt-main form{display:flex;border:1px solid var(--tt-border);border-radius:12px;overflow:hidden;background:#f8fafb;transition:border-color .18s,box-shadow .18s}.tt-main form:focus-within{border-color:var(--tt-teal);box-shadow:0 0 0 3px rgba(20,139,147,.12)}.tt-main input{border:0!important;box-shadow:none!important;background:transparent!important;flex:1;padding:13px 16px}.tt-main button{border:0;background:var(--tt-teal);color:#fff;padding:0 24px;font-weight:800}.tt-cart{position:relative;text-decoration:none;color:var(--tt-navy);font-weight:800;border:1px solid var(--tt-border);border-radius:12px;padding:12px 17px;transition:.18s}.tt-cart:hover{border-color:var(--tt-teal);transform:translateY(-1px)}.tt-cart b{position:absolute;right:-7px;top:-9px;background:var(--tt-orange);color:#fff;border-radius:50%;min-width:22px;height:22px;text-align:center;line-height:22px}.tt-nav ul{display:flex;gap:30px;list-style:none;margin:0;padding:13px 0;border-top:1px solid #edf0f2}.tt-nav a{text-decoration:none;color:var(--tt-navy);font-weight:750;font-size:14px;letter-spacing:.01em}.tt-nav a:hover{color:var(--tt-teal)}@media(max-width:767px){.tt-main{grid-template-columns:1fr auto;gap:12px}.tt-main form{grid-column:1/-1;grid-row:2}.tt-nav{overflow-x:auto}.tt-nav ul{gap:20px;white-space:nowrap}.tt-main button{padding:0 16px}}</style><?php}}
\Elementor\Plugin::instance()->widgets_manager->register(new Terttus_Header_Widget());
